"use client"

import * as React from "react"

import {
  type Extraction,
  type ExtractionSources,
  type ViewerAdapter,
} from "@/lib/retab"
import { cn } from "@/lib/utils"
import { useExtractionSources } from "@/hooks/use-retab"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"

export interface ExtractionViewerProps {
  extraction: Extraction
  /**
   * Field-level source grounding (from the extraction `/sources` endpoint).
   * When present, leaves expose where the value came from. If omitted, an
   * `adapter` with `getExtractionSources` will be used to fetch it lazily.
   */
  sources?: ExtractionSources
  adapter?: ViewerAdapter
  /** Called with a leaf's source when the user selects it (e.g. to scroll a PDF). */
  onSelectSource?: (path: string, source: unknown) => void
  className?: string
}

export function ExtractionViewer({
  extraction,
  sources,
  adapter,
  onSelectSource,
  className,
}: ExtractionViewerProps) {
  const output = extraction.output ?? {}
  const phase = useViewerPhase({
    status: extraction.status,
    error: extraction.error,
    hasOutput: output != null && Object.keys(output).length > 0,
  })

  // Lazily fetch grounding through the adapter when sources aren't passed in.
  const fetched = useExtractionSources(
    adapter,
    extraction.id,
    !sources && Boolean(adapter?.getExtractionSources)
  )
  const effectiveSources = sources ?? fetched.data ?? undefined
  const consensusCount = extraction.consensus?.choices?.length ?? 0

  return (
    <RetabViewerShell
      title={extraction.file?.filename ?? "Extraction"}
      status={extraction.status}
      error={extraction.error}
      phase={phase}
      emptyMessage="The extraction produced no fields."
      actions={
        consensusCount > 0 ? (
          <span className="text-xs text-muted-foreground">
            consensus of {consensusCount}
          </span>
        ) : null
      }
      className={className}
    >
      <div className="p-3 font-mono text-xs">
        <JsonNode
          name={null}
          value={output}
          sourceNode={effectiveSources?.sources}
          path=""
          depth={0}
          onSelectSource={onSelectSource}
        />
      </div>
    </RetabViewerShell>
  )
}

interface JsonNodeProps {
  name: string | null
  value: unknown
  sourceNode: unknown
  path: string
  depth: number
  onSelectSource?: (path: string, source: unknown) => void
}

function JsonNode({
  name,
  value,
  sourceNode,
  path,
  depth,
  onSelectSource,
}: JsonNodeProps) {
  const isObject = value != null && typeof value === "object"
  const isArray = Array.isArray(value)

  if (!isObject) {
    return (
      <LeafRow
        name={name}
        value={value}
        sourceNode={sourceNode}
        path={path}
        onSelectSource={onSelectSource}
      />
    )
  }

  const entries = isArray
    ? (value as unknown[]).map((v, i) => [String(i), v] as const)
    : Object.entries(value as Record<string, unknown>)

  return (
    <Collapsible defaultOpen={depth < 2}>
      <div className="flex items-center gap-1">
        <CollapsibleTrigger className="group flex items-center gap-1 rounded px-1 py-0.5 hover:bg-muted">
          <span className="text-muted-foreground transition-transform group-data-[panel-open]:rotate-90">
            ▸
          </span>
          {name != null ? (
            <span className="text-foreground/80">{name}</span>
          ) : null}
          <span className="text-muted-foreground">
            {isArray ? `[${entries.length}]` : `{${entries.length}}`}
          </span>
        </CollapsibleTrigger>
      </div>
      <CollapsibleContent>
        <div
          className="flex flex-col gap-0.5 border-l border-border/60 pl-3"
          style={{ marginLeft: 6 }}
        >
          {entries.map(([key, child]) => {
            const childSource = getSourceChild(sourceNode, key)
            return (
              <JsonNode
                key={key}
                name={key}
                value={child}
                sourceNode={childSource}
                path={path ? `${path}.${key}` : key}
                depth={depth + 1}
                onSelectSource={onSelectSource}
              />
            )
          })}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

function LeafRow({
  name,
  value,
  sourceNode,
  path,
  onSelectSource,
}: {
  name: string | null
  value: unknown
  sourceNode: unknown
  path: string
  onSelectSource?: (path: string, source: unknown) => void
}) {
  const source = extractLeafSource(sourceNode)
  const badge = source ? sourceBadge(source) : null

  return (
    <div className="flex items-baseline gap-2 px-1 py-0.5">
      {name != null ? (
        <span className="text-foreground/80">{name}:</span>
      ) : null}
      <span className={valueToneClass(value)}>{formatScalar(value)}</span>
      {badge ? (
        <button
          type="button"
          onClick={() => onSelectSource?.(path, source)}
          className="ml-auto inline-flex items-center rounded bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-muted-foreground/20"
        >
          {badge}
        </button>
      ) : null}
    </div>
  )
}

// --- source helpers ---------------------------------------------------------

/** Descend into a source node by key, transparently unwrapping {value, source}. */
function getSourceChild(sourceNode: unknown, key: string): unknown {
  if (sourceNode == null || typeof sourceNode !== "object") return undefined
  // A grounded leaf looks like { value, source }; descend into its value.
  if ("value" in (sourceNode as Record<string, unknown>) && "source" in (sourceNode as Record<string, unknown>)) {
    const inner = (sourceNode as { value: unknown }).value
    if (inner != null && typeof inner === "object") {
      return (inner as Record<string, unknown>)[key]
    }
    return undefined
  }
  return (sourceNode as Record<string, unknown>)[key]
}

function extractLeafSource(sourceNode: unknown): Record<string, unknown> | null {
  if (sourceNode == null || typeof sourceNode !== "object") return null
  if ("source" in (sourceNode as Record<string, unknown>)) {
    const s = (sourceNode as { source: unknown }).source
    return s && typeof s === "object" ? (s as Record<string, unknown>) : null
  }
  return null
}

function sourceBadge(source: Record<string, unknown>): string | null {
  const bbox = source.bbox as { page?: number } | undefined
  if (bbox?.page != null) return `p.${bbox.page}`
  if (typeof source.cell === "string") return source.cell
  if (source.span) return "text"
  return "source"
}

// --- scalar formatting ------------------------------------------------------

function formatScalar(value: unknown): string {
  if (value === null) return "null"
  if (typeof value === "string") return `"${value}"`
  if (typeof value === "boolean" || typeof value === "number") return String(value)
  return String(value)
}

function valueToneClass(value: unknown): string {
  if (typeof value === "string") return "text-emerald-600 dark:text-emerald-400"
  if (typeof value === "number") return "text-blue-600 dark:text-blue-400"
  if (typeof value === "boolean") return "text-purple-600 dark:text-purple-400"
  if (value === null) return "text-muted-foreground"
  return "text-foreground"
}

export { type Extraction }
